import { BadgeIndianRupee, Box, HelpCircle, LayoutDashboard, LogOut, Megaphone, Package, ShoppingCart, Star, Store, Users } from 'lucide-react'
import AvalAngadiLogo from '../../../assets/aval-angadi-logo.png'
const items = [[LayoutDashboard, 'Dashboard'], [Package, 'Products'], [ShoppingCart, 'Orders'], [Box, 'Inventory'], [Users, 'Customers'], [Star, 'Reviews'], [Megaphone, 'Promotions'], [BadgeIndianRupee, 'Payments'], [Store, 'Store Settings'], [Users, 'Profile'], [HelpCircle, 'Help']]
export default function VendorSidebar({ activePage, onNavigate }) { return <aside className="vendor-sidebar"><div className="vendor-brand"><span style={{ border: 0 }}><img src={AvalAngadiLogo} alt="Aval Angadi" style={{ width: '34px', height: '34px', objectFit: 'contain' }} /></span><div><strong>AVAL ANGADI</strong><small>Vendor Dashboard</small></div></div><nav>{items.map(([Icon, label]) => <button key={label} type="button" className={activePage === label ? 'active' : ''} onClick={() => onNavigate(label)}><Icon size={18} />{label}</button>)}</nav><div className="vendor-growth"><span>✦</span><strong>Grow your store</strong><p>Run promotions and boost your sales.</p><button type="button" onClick={() => onNavigate('Promotions')}>Create Promotion</button></div><button className="vendor-logout" type="button"><LogOut size={18} />Logout</button></aside> }
